INSERT INTO public_wordbook_words (
  wordbook_id,
  word,
  meaning,
  phonetic,
  example_sentence,
  source_rank,
  metadata
)
SELECT
  public_wordbooks.id,
  seed.word,
  seed.meaning,
  seed.phonetic,
  seed.example_sentence,
  seed.source_rank,
  seed.metadata
FROM public_wordbooks
