ON CONFLICT (wordbook_id, word)
DO UPDATE SET
  meaning = EXCLUDED.meaning,
  phonetic = EXCLUDED.phonetic,
  example_sentence = EXCLUDED.example_sentence,
  source_rank = EXCLUDED.source_rank,
  metadata = EXCLUDED.metadata;


